{"op":"define","frontend":"flow","source":"word customer.renewal-balance(customer: Customer, subscription: Subscription) -> Float {
    effects none
    let initialBalance = if ::equals(customer::kind(customer), "premium") {
        float::multiply(customer::balance(customer), 0.9)
    } else {
        customer::balance(customer)
    }
    if ::equals(subscription::term(subscription), "annual") {
        if subscription::renewable(subscription) {
            float::multiply(initialBalance, 0.95)
        } else {
            initialBalance
        }
    } else {
        initialBalance
    }
}
test customer.renewal-balance/premium_annual_renewable {
    customer::renewal-balance(customer::new("premium", 100.0), subscription::new("annual", true)) => 85.5
}
test customer.renewal-balance/standard_annual_renewable {
    customer::renewal-balance(customer::new("standard", 100.0), subscription::new("annual", true)) => 95.0
}
test customer.renewal-balance/premium_annual_nonrenewable {
    customer::renewal-balance(customer::new("premium", 100.0), subscription::new("annual", false)) => 90.0
}
test customer.renewal-balance/premium_monthly_renewable {
    customer::renewal-balance(customer::new("premium", 100.0), subscription::new("monthly", true)) => 90.0
}
test customer.renewal-balance/strings_are_exact {
    customer::renewal-balance(customer::new("Premium", 100.0), subscription::new("Annual", true)) => 100.0
}
test customer.renewal-balance/zero_balance {
    customer::renewal-balance(customer::new("premium", 0.0), subscription::new("annual", true)) => 0.0
}"}

